interface Item { id: number; name: string }
function ItemList({ initialItems }: { initialItems: Item[] }) {
  const [items, setItems] = useState<Item[]>(initialItems);
  const remove = (id: number) => setItems(current => current.filter(item => item.id !== id));
  return <ul>{items.map(item => <li key={item.id}>{item.name}<button onClick={() => remove(item.id)}>Elimina</button></li>)}</ul>;
}

